package com.tainted.community.blackbox;

import static com.tainted.community.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.community.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts
 *
 * Black-box 통합 테스트: GET /internal/posts (listPosts)
 * 모든 포스트를 생성 순서 역순으로 조회한다.
 * DB에 저장된 포스트가 없어도 빈 리스트를 반환한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CommunityListBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "SEQ", Long.toString(seq),
                "ID", "T" + testId(info),
                "UID", "U" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/community-list-teardown.sql", p);
        executeSqlTemplate("sql/community-list-setup.sql", p);
    }

    @Test
    void NTC_listPosts_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("size()", equalTo("2"))
                    .body("[0].id", equalTo("${ID}2"))
                    .body("[0].title", equalTo("Another Post Title"))
                    .body("[0].category", equalTo("family"))
                    .body("[1].id", equalTo("${ID}"))
                    .body("[1].title", equalTo("Test Post Title"));
        } finally {
            executeSqlTemplate("sql/community-list-teardown.sql", p);
        }
    }

    @Test
    void ATC_listPosts_empty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/internal/posts")
            .then()
                    .statusCode(200)
                    .body("size()", equalTo("0"));
        } finally {
            executeSqlTemplate("sql/community-list-teardown.sql", p);
        }
    }
}

